<?php defined('_JEXEC') or die; use Joomla\CMS\HTML\HTMLHelper; use Joomla\CMS\Router\Route; $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<div class="xdecaro-scope"><section class="xdecaro-card mb-3"><div class="xdecaro-card__header"><h1 class="xdecaro-card__title"><?= $e($this->item->title) ?></h1><p class="xdecaro-card__description"><?= $e($this->item->start_at) ?> · <?= $e($this->item->location) ?></p></div><div class="xdecaro-card__body"><p><?= nl2br($e($this->item->description)) ?></p><?php if($this->sessions):?><h2>Sessioni</h2><ul><?php foreach($this->sessions as $s):?><li><?= $e($s->title) ?> — <?= $e($s->start_at) ?><?= $s->location?' · '.$e($s->location):'' ?></li><?php endforeach;?></ul><?php endif;?></div></section><?php if((int)$this->item->registration_open===1):?><section class="xdecaro-card"><div class="xdecaro-card__header"><h2 class="xdecaro-card__title">Registrazione</h2></div><div class="xdecaro-card__body"><form method="post" action="<?= Route::_('index.php?option=com_decaroevents&task=registration.submit') ?>"><input type="hidden" name="event_id" value="<?= (int)$this->item->id ?>"><div class="xdecaro-field mb-3"><label class="xdecaro-label" for="de-name">Nome</label><input class="xdecaro-input" id="de-name" name="name" required maxlength="255"></div><div class="xdecaro-field mb-3"><label class="xdecaro-label" for="de-email">Email</label><input class="xdecaro-input" type="email" id="de-email" name="email" required maxlength="320"></div><?php if($this->sessions):?><div class="xdecaro-field mb-3"><label class="xdecaro-label" for="de-session">Sessione</label><select class="xdecaro-select" id="de-session" name="session_id"><option value="0">Evento generale</option><?php foreach($this->sessions as $s):?><option value="<?= (int)$s->id ?>"><?= $e($s->title) ?> — <?= $e($s->start_at) ?></option><?php endforeach;?></select></div><?php endif;?><button class="xdecaro-button xdecaro-button--primary" type="submit">Registrati</button><?= HTMLHelper::_('form.token') ?></form></div></section><?php endif;?></div>
